// OML_O35 - Laboratory order for multiple orders related to a single container of a sp
// The trigger event for this message is any change to a laboratory order. Such changes include submission of new orders, cancellations, updates, etc., where multiple orders are associated with a single sample which may be carried in multiple containers. OML messages can originate also with a placer, filler, or an interested third party.
//
// This allows for a Specimen-centric message with multiple orders per specimen grouped by the specimen.
//
// The following message structure may be used for the communication of laboratory and other order messages and must be used for lab automation messages where the message requires Specimen/container information to group a number of orders.
//
// In relationship to triggers O21, O33, and O35, this message/trigger (O35) should be used for laboratory orders where there is 1 or more Specimens with 1 to many containers and each container may have 1 to many orders with previous result(s) per container.
type OML_O35 struct {
	MSH      *MSH               `hl7:"MSH,required"`
	SFT      []SFT              `hl7:"SFT"`
	UAC      *UAC               `hl7:"UAC"`
	NTE      []NTE              `hl7:"NTE"`
	PATIENT  *OML_O35_PATIENT   `hl7:"PATIENT"`
	SPECIMEN []OML_O35_SPECIMEN `hl7:"SPECIMEN,required"`
}

func NewOML_O35() *OML_O35 {
	return &OML_O35{
		MSH: NewMSH(NewMSG().SetMessageCode("OML").SetTriggerEvent("O35").SetMessageStructure("OML_O35")),
	}
}

func (m *OML_O35) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OML_O35.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OML_O35.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O35.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("OML_O35.UAC: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O35.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OML_O35.PATIENT: %w", err)
		}
	}

	if len(m.SPECIMEN) == 0 {
		return fmt.Errorf("OML_O35.SPECIMEN is required")
	}
	for _, item := range m.SPECIMEN {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OML_O35.SPECIMEN: %w", err)
		}
	}
	return nil
}

func (m *OML_O35) SetMSH(v *MSH) *OML_O35 {
	m.MSH = v
	return m
}

