// OSM_R26 - Unsolicited Specimen Shipment Manifest Message
// The OSM^R26 Unsolicited Specimen Shipment Manifest message is used to communicate the contents of a specimen shipment to a specimen receiver (typically a laboratory). The message documents details regard the following:
// - Shipment information including sender, receiver, shipper, shipping container, etc.;
// - Specimens in the shipment;
// - Specimen containers; and,
// - Identification of persons/places/things associated with the specimens.
type OSM_R26 struct {
	MSH      *MSH               `hl7:"MSH,required"`
	SFT      []SFT              `hl7:"SFT"`
	UAC      *UAC               `hl7:"UAC"`
	SHIPMENT []OSM_R26_SHIPMENT `hl7:"SHIPMENT,required"`
}

func NewOSM_R26() *OSM_R26 {
	return &OSM_R26{
		MSH: NewMSH(NewMSG().SetMessageCode("OSM").SetTriggerEvent("R26").SetMessageStructure("OSM_R26")),
	}
}

func (m *OSM_R26) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OSM_R26.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OSM_R26.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OSM_R26.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("OSM_R26.UAC: %w", err)
		}
	}

	if len(m.SHIPMENT) == 0 {
		return fmt.Errorf("OSM_R26.SHIPMENT is required")
	}
	for _, item := range m.SHIPMENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OSM_R26.SHIPMENT: %w", err)
		}
	}
	return nil
}

func (m *OSM_R26) SetMSH(v *MSH) *OSM_R26 {
	m.MSH = v
	return m
}

func (m *OSM_R26) AddSFT(v SFT) *OSM_R26 {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *OSM_R26) SetUAC(v *UAC) *OSM_R26 {
	m.UAC = v
	return m
}

