// OUL_R23 - Unsolicited Specimen Container Oriented Observation Message
// This message was designed to accommodate specimen oriented testing. It should be applicable to, for example, laboratory automation systems requiring container.
//
// Generally this construct allows transfer of multiple results related to one or more specific containers with one or more specimens from a patient.
//
// In addition to the patient results themselves it permits the communication of the following kinds of information:
// - Analysis results of a non patient related sample (e.g., environmental) – patient related segments (e.g., PID, PD1, PV1, PV2) are optional.
// - Analysis results to a particular container with QC sample and the lot and manufacturer information about this sample (SAC-INV segments).
// - Basic identification data (lot, manufacturer, etc.) of the reagents and other substances involved in the generation of analysis results (TCD-SID segments).
//
// Refer to Chapter 13 Laboratory Automation for additional examples of usage of SAC.
type OUL_R23 struct {
	MSH      *MSH               `hl7:"MSH,required"`
	SFT      []SFT              `hl7:"SFT"`
	UAC      *UAC               `hl7:"UAC"`
	NTE      *NTE               `hl7:"NTE"`
	PATIENT  *OUL_R23_PATIENT   `hl7:"PATIENT"`
	NK1      []NK1              `hl7:"NK1"`
	SPECIMEN []OUL_R23_SPECIMEN `hl7:"SPECIMEN,required"`
	DSC      *DSC               `hl7:"DSC"`
}

func NewOUL_R23() *OUL_R23 {
	return &OUL_R23{
		MSH: NewMSH(NewMSG().SetMessageCode("OUL").SetTriggerEvent("R23").SetMessageStructure("OUL_R23")),
	}
}

func (m *OUL_R23) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("OUL_R23.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.UAC: %w", err)
		}
	}

	if m.NTE != nil {
		if err := m.NTE.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.NTE: %w", err)
		}
	}

	if m.PATIENT != nil {
		if err := m.PATIENT.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.PATIENT: %w", err)
		}
	}

	for _, item := range m.NK1 {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.NK1: %w", err)
		}
	}

	if len(m.SPECIMEN) == 0 {
		return fmt.Errorf("OUL_R23.SPECIMEN is required")
	}
	for _, item := range m.SPECIMEN {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.SPECIMEN: %w", err)
		}
	}

	if m.DSC != nil {
		if err := m.DSC.Validate(); err != nil {
			return fmt.Errorf("OUL_R23.DSC: %w", err)
		}
	}
	return nil
}

