// PPG_PCG - PC/ pathway (goal-oriented) add
type PPG_PCG struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	UAC          *UAC                  `hl7:"UAC"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPG_PCG_PATIENTVISIT `hl7:"PATIENT_VISIT"`
	PATHWAY      []PPG_PCG_PATHWAY     `hl7:"PATHWAY,required"`
}

func NewPPG_PCG() *PPG_PCG {
	return &PPG_PCG{
		MSH: NewMSH(NewMSG().SetMessageCode("PPG").SetTriggerEvent("PCG").SetMessageStructure("PPG_PCG")),
	}
}

func (m *PPG_PCG) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPG_PCG.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.UAC: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPG_PCG.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PATHWAY) == 0 {
		return fmt.Errorf("PPG_PCG.PATHWAY is required")
	}
	for _, item := range m.PATHWAY {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPG_PCG.PATHWAY: %w", err)
		}
	}
	return nil
}

func (m *PPG_PCG) SetMSH(v *MSH) *PPG_PCG {
	m.MSH = v
	return m
}

func (m *PPG_PCG) AddSFT(v SFT) *PPG_PCG {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *PPG_PCG) SetUAC(v *UAC) *PPG_PCG {
	m.UAC = v
	return m
}

func (m *PPG_PCG) SetPID(v *PID) *PPG_PCG {
	m.PID = v
	return m
}

func (m *PPG_PCG) SetPATIENTVISIT(v *PPG_PCG_PATIENTVISIT) *PPG_PCG {
	m.PATIENTVISIT = v
	return m
}

