// PPG_PCH - PC/ pathway (goal-oriented) update
type PPG_PCH struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	UAC          *UAC                  `hl7:"UAC"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPG_PCH_PATIENTVISIT `hl7:"PATIENT_VISIT"`
	PATHWAY      []PPG_PCH_PATHWAY     `hl7:"PATHWAY,required"`
}

func NewPPG_PCH() *PPG_PCH {
	return &PPG_PCH{
		MSH: NewMSH(NewMSG().SetMessageCode("PPG").SetTriggerEvent("PCH").SetMessageStructure("PPG_PCH")),
	}
}

func (m *PPG_PCH) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPG_PCH.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.UAC: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPG_PCH.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PATHWAY) == 0 {
		return fmt.Errorf("PPG_PCH.PATHWAY is required")
	}
	for _, item := range m.PATHWAY {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPG_PCH.PATHWAY: %w", err)
		}
	}
	return nil
}

func (m *PPG_PCH) SetMSH(v *MSH) *PPG_PCH {
	m.MSH = v
	return m
}

func (m *PPG_PCH) AddSFT(v SFT) *PPG_PCH {
	m.SFT = append(m.SFT, v)
	return m
}

func (m *PPG_PCH) SetUAC(v *UAC) *PPG_PCH {
	m.UAC = v
	return m
}

func (m *PPG_PCH) SetPID(v *PID) *PPG_PCH {
	m.PID = v
	return m
}

func (m *PPG_PCH) SetPATIENTVISIT(v *PPG_PCH_PATIENTVISIT) *PPG_PCH {
	m.PATIENTVISIT = v
	return m
}

func (m *PPG_PCH) AddPATHWAY(v PPG_PCH_PATHWAY) *PPG_PCH {
	m.PATHWAY = append(m.PATHWAY, v)
	return m
}

