// PPP_PCB - PC/ pathway (problem-oriented) add
type PPP_PCB struct {
	MSH          *MSH                  `hl7:"MSH,required"`
	SFT          []SFT                 `hl7:"SFT"`
	UAC          *UAC                  `hl7:"UAC"`
	PID          *PID                  `hl7:"PID,required"`
	PATIENTVISIT *PPP_PCB_PATIENTVISIT `hl7:"PATIENT_VISIT"`
	PATHWAY      []PPP_PCB_PATHWAY     `hl7:"PATHWAY,required"`
}

func NewPPP_PCB() *PPP_PCB {
	return &PPP_PCB{
		MSH: NewMSH(NewMSG().SetMessageCode("PPP").SetTriggerEvent("PCB").SetMessageStructure("PPP_PCB")),
	}
}

func (m *PPP_PCB) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPP_PCB.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.UAC: %w", err)
		}
	}

	if m.PID == nil {
		return fmt.Errorf("PPP_PCB.PID is required")
	}
	if m.PID != nil {
		if err := m.PID.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.PID: %w", err)
		}
	}

	if m.PATIENTVISIT != nil {
		if err := m.PATIENTVISIT.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.PATIENTVISIT: %w", err)
		}
	}

	if len(m.PATHWAY) == 0 {
		return fmt.Errorf("PPP_PCB.PATHWAY is required")
	}
	for _, item := range m.PATHWAY {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPP_PCB.PATHWAY: %w", err)
		}
	}
	return nil
}

func (m *PPP_PCB) SetMSH(v *MSH) *PPP_PCB {
	m.MSH = v
	return m
}

func (m *PPP_PCB) AddSFT(v SFT) *PPP_PCB {
	m.SFT = append(m.SFT, v)
	return m
}

