// PPT_PCL - PC/ pathway (goal-oriented) query response
// Retained for backwards compatibility only in version 2.4 and later; refer to Chapter 5, section 5.4.  The original mode query and the QRD/QRF segments have been replaced.
//
// The following trigger/message event is served by PPT (a response from the system responsible for maintaining the goal-oriented pathway information).
type PPT_PCL struct {
	MSH     *MSH              `hl7:"MSH,required"`
	SFT     []SFT             `hl7:"SFT"`
	UAC     *UAC              `hl7:"UAC"`
	MSA     *MSA              `hl7:"MSA,required"`
	ERR     []ERR             `hl7:"ERR"`
	QAK     *QAK              `hl7:"QAK"`
	QRD     *QRD              `hl7:"QRD,required"`
	PATIENT []PPT_PCL_PATIENT `hl7:"PATIENT,required"`
}

func NewPPT_PCL() *PPT_PCL {
	return &PPT_PCL{
		MSH: NewMSH(NewMSG().SetMessageCode("PPT").SetTriggerEvent("PCL").SetMessageStructure("PPT_PCL")),
	}
}

func (m *PPT_PCL) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("PPT_PCL.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.MSH: %w", err)
		}
	}

	for _, item := range m.SFT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.SFT: %w", err)
		}
	}

	if m.UAC != nil {
		if err := m.UAC.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.UAC: %w", err)
		}
	}

	if m.MSA == nil {
		return fmt.Errorf("PPT_PCL.MSA is required")
	}
	if m.MSA != nil {
		if err := m.MSA.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.MSA: %w", err)
		}
	}

	for _, item := range m.ERR {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.ERR: %w", err)
		}
	}

	if m.QAK != nil {
		if err := m.QAK.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.QAK: %w", err)
		}
	}

	if m.QRD == nil {
		return fmt.Errorf("PPT_PCL.QRD is required")
	}
	if m.QRD != nil {
		if err := m.QRD.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.QRD: %w", err)
		}
	}

	if len(m.PATIENT) == 0 {
		return fmt.Errorf("PPT_PCL.PATIENT is required")
	}
	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("PPT_PCL.PATIENT: %w", err)
		}
	}
	return nil
}

func (m *PPT_PCL) SetMSH(v *MSH) *PPT_PCL {
	m.MSH = v
	return m
}

func (m *PPT_PCL) AddSFT(v SFT) *PPT_PCL {
	m.SFT = append(m.SFT, v)
	return m
}

