// SRM_S11 - Request deletion of service/resource on appointment
// A request deletion of service/resource is sent by the placer application to the filler application to request that a scheduled appointment requiring a service or resource entered in error be removed from the system. A delete trigger event should only be used when a service or resource has been erroneously attached to an appointment, and must be removed from the schedule so that it does not affect any statistical processing. A delete trigger event differs from a cancel trigger event in that a delete acts to remove an error, whereas a cancel acts to prevent a valid request from occurring. This trigger event should only be used on appointments that have not been completed, or on parent appointments whose children have not been completed. If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the modified appointment
type SRM_S11 struct {
	MSH       *MSH                `hl7:"MSH,required"`
	ARQ       *ARQ                `hl7:"ARQ,required"`
	APR       *APR                `hl7:"APR"`
	NTE       []NTE               `hl7:"NTE"`
	PATIENT   []SRM_S11_PATIENT   `hl7:"PATIENT"`
	RESOURCES []SRM_S11_RESOURCES `hl7:"RESOURCES,required"`
}

func NewSRM_S11() *SRM_S11 {
	return &SRM_S11{
		MSH: NewMSH(NewMSG().SetMessageCode("SRM").SetTriggerEvent("S11").SetMessageStructure("SRM_S11")),
	}
}

func (m *SRM_S11) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRM_S11.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.MSH: %w", err)
		}
	}

	if m.ARQ == nil {
		return fmt.Errorf("SRM_S11.ARQ is required")
	}
	if m.ARQ != nil {
		if err := m.ARQ.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.ARQ: %w", err)
		}
	}

	if m.APR != nil {
		if err := m.APR.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.APR: %w", err)
		}
	}

	for _, item := range m.NTE {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.NTE: %w", err)
		}
	}

	for _, item := range m.PATIENT {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.PATIENT: %w", err)
		}
	}

	if len(m.RESOURCES) == 0 {
		return fmt.Errorf("SRM_S11.RESOURCES is required")
	}
	for _, item := range m.RESOURCES {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRM_S11.RESOURCES: %w", err)
		}
	}
	return nil
}

