// SRR_S03 - Scheduled Request Response - Request Appointment Modification
// This message transmits a request for modification of an existing appointment to a filler application.  This trigger event is used to request the modification of information on an existing appointment, outside of the need to reschedule, cancel, discontinue or delete the appointment, or to add, modify, cancel, discontinue, or delete services and/or resources on the appointment.  This trigger event should only be used for appointments that have not been completed, or for parent appointments whose children have not been completed.  If it is successful, an application acknowledgment is returned, optionally containing an SCH segment and related detail segments describing the new information for the modified appointment
type SRR_S03 struct {
	MSH      *MSH              `hl7:"MSH,required"`
	MSA      *MSA              `hl7:"MSA,required"`
	ERR      []ERR             `hl7:"ERR"`
	SCHEDULE *SRR_S03_SCHEDULE `hl7:"SCHEDULE"`
}

func NewSRR_S03() *SRR_S03 {
	return &SRR_S03{
		MSH: NewMSH(NewMSG().SetMessageCode("SRR").SetTriggerEvent("S03").SetMessageStructure("SRR_S03")),
	}
}

func (m *SRR_S03) Validate() error {

	if m.MSH == nil {
		return fmt.Errorf("SRR_S03.MSH is required")
	}
	if m.MSH != nil {
		if err := m.MSH.Validate(); err != nil {
			return fmt.Errorf("SRR_S03.MSH: %w", err)
		}
	}

	if m.MSA == nil {
		return fmt.Errorf("SRR_S03.MSA is required")
	}
	if m.MSA != nil {
		if err := m.MSA.Validate(); err != nil {
			return fmt.Errorf("SRR_S03.MSA: %w", err)
		}
	}

	for _, item := range m.ERR {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("SRR_S03.ERR: %w", err)
		}
	}

	if m.SCHEDULE != nil {
		if err := m.SCHEDULE.Validate(); err != nil {
			return fmt.Errorf("SRR_S03.SCHEDULE: %w", err)
		}
	}
	return nil
}

func (m *SRR_S03) SetMSH(v *MSH) *SRR_S03 {
	m.MSH = v
	return m
}

func (m *SRR_S03) SetMSA(v *MSA) *SRR_S03 {
	m.MSA = v
	return m
}

